package counter

type Counter struct {
	value int
}

func NewCounter() *Counter {
	return &Counter{}
}

func (c *Counter) Increment() {
	c.value++
}

func (c *Counter) Decrement() {
	c.value--
}

func (c *Counter) Value() int {
	return c.value
}

func (c *Counter) Reset() {
	c.value = 0
}

package counter

import "testing"

func TestCounterBasic(t *testing.T) {
	c := NewCounter()
	c.Increment()
	c.Increment()
	c.Increment()
	if c.Value() != 3 {
		t.Fatalf("want 3 got %d", c.Value())
	}
}

func TestCounterDecrement(t *testing.T) {
	c := NewCounter()
	c.Increment()
	c.Decrement()
	if c.Value() != 0 {
		t.Fatalf("want 0 got %d", c.Value())
	}
}

func TestCounterReset(t *testing.T) {
	c := NewCounter()
	c.Increment()
	c.Reset()
	if c.Value() != 0 {
		t.Fatalf("want 0 got %d", c.Value())
	}
}

