Add sync.Mutex protection to counter.go. Keep the same API.

import "sync"

type Counter struct {
    mu    sync.Mutex
    value int
}

// Wrap each method with mu.Lock() / defer mu.Unlock():
func (c *Counter) Increment() { c.mu.Lock(); defer c.mu.Unlock(); c.value++ }
func (c *Counter) Decrement() { c.mu.Lock(); defer c.mu.Unlock(); c.value-- }
func (c *Counter) Value() int { c.mu.Lock(); defer c.mu.Unlock(); return c.value }
func (c *Counter) Reset() { c.mu.Lock(); defer c.mu.Unlock(); c.value = 0 }

All 5 tests (3 original + 2 new concurrent) in the solution test file must pass with -race.
Run: go test -race ./...
